import '../../../../../../Core/Models/product_model.dart';class ProductPreviewEntities extends ProductModel {  final String image;  ProductPreviewEntities({    required super.id,    required this.image,    required super.name,    required super.price,    required super.discountPrice,    required super.description,    required super.additionalInfo,  }) : super(          // slug: '',          // categoryId: 0,          // dimensions: '',          // featured: 0,          // popular: 0,          // status: 0,          // quantity: 0,          // createdAt: null,          // updatedAt: null,          primaryImage: PrimaryImage(            image: "",            id: 0,            productId: id,            imageUrl: image,            isPrimary: 1,            createdAt: null,            updatedAt: null,          ),          // category: null,        );  factory ProductPreviewEntities.fromJson(Map<dynamic, dynamic> json) {    return ProductPreviewEntities(      id: json['id'] ?? 0,      image: json['image_url'] ?? '',      name: json['name'] ?? '',      price: json['price'] ?? '',      discountPrice: json['discount_price'] ?? '',      description: json["description"] ?? "",      additionalInfo: json["additional_info"] ?? "",    );  }  factory ProductPreviewEntities.fromProduct(ProductModel product) {    return ProductPreviewEntities(      id: product.id,      image: product.primaryImage?.imageUrl ?? "",      name: product.name,      price: product.price,      discountPrice: product.discountPrice, description: product.description, additionalInfo:product.additionalInfo,    );  }  Map<String, dynamic> toMap() {    return {      'id': id,      'name': name,      'price': price,      'discount_price': discountPrice,      'image_url': primaryImage?.imageUrl ?? '',      'description': description ,      'additional_info':additionalInfo ,    };  }}